def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    prev_high = 0.0
    prev_mid = 0.0
    cindy_bid = None
    david_bid = None

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid > prev_high:
                    prev_mid = prev_high
                    prev_high = float(bid)
                elif bid > prev_mid:
                    prev_mid = float(bid)
                if agent_id == 'Cindy':
                    cindy_bid = float(bid)
                if agent_id == 'David':
                    david_bid = float(bid)

    if not alive:
        return float(min(budget, 5.0))

    scarcity = float(WATER_REQ) / max(1.0, float(supply))
    danger = 0
    if hp <= 3:
        danger += 2
    elif hp <= 5:
        danger += 1
    if no_water_days >= 2:
        danger += 2
    elif no_water_days >= 1:
        danger += 1
    if supply <= 16:
        danger += 1

    if cindy_bid is None:
        cindy_bid = 160.0
    if david_bid is None:
        david_bid = 95.0

    if danger >= 4:
        target = max(david_bid + 4.0, 138.0)
        if budget > cindy_bid + 2.0 and hp <= 2:
            target = cindy_bid + 2.0
    elif danger >= 2:
        target = max(david_bid + 3.0, prev_mid + 2.0, 96.0)
        if supply <= 16:
            target = max(target, 112.0)
    else:
        if prev_high >= 150.0:
            target = 22.0 if supply >= 20 else 35.0
        elif prev_high >= 120.0:
            target = 48.0 if supply >= 20 else 62.0
        else:
            target = max(28.0, prev_high * 0.55)

    reserve_days = 3 if hp > 4 else 2
    reserve = reserve_days * DAILY_SALARY
    affordable = budget - reserve
    if affordable < 0:
        affordable = budget * 0.6

    if danger == 0 and scarcity < 0.7:
        target *= 0.85
    elif scarcity > 0.8:
        target *= 1.08

    bid = min(float(budget), float(max(0.0, affordable)), float(target))

    if danger >= 3 and bid < min(float(budget), 90.0):
        bid = min(float(budget), max(float(bid), 90.0))

    if hp <= 2:
        bid = min(float(budget), max(float(bid), 120.0))

    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))

    # Identify alive opponents and read yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            prev = opp.get('previous_trace', {}) or {}
            prev_bid = prev.get('bid', None)
            alive_opps.append((opp_id, opp, prev_bid))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Yesterday pressure from bids
    prev_bids = [b for (_, _, b) in alive_opps if isinstance(b, (int, float)) and b is not None]
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely needed/available
    # Supply is total units; our requirement is WATER_REQ per day.
    # If supply is near minimum, competition is higher.
    tight_supply = supply <= (MIN_SUPPLY + 0.5)

    # Strategy: If Cindy/Alex were aggressive yesterday, we bid moderately high to secure water when tight.
    # Otherwise, conserve and bid just above likely low bidders.
    # Use our HP to decide risk.
    if my_hp <= 2:
        # Desperate: try to secure water regardless
        bid = DAILY_SALARY * (0.85 if tight_supply else 0.75)
    else:
        # Determine target bid level based on yesterday highest bid
        if highest_prev_bid >= DAILY_SALARY * 1.6:
            # Very aggressive opponent yesterday (likely Cindy). Outbid slightly only when supply tight.
            if tight_supply:
                bid = min(my_budget, highest_prev_bid + 5.0)
            else:
                bid = min(my_budget, max(DAILY_SALARY * 0.55, highest_prev_bid * 0.75))
        elif highest_prev_bid >= DAILY_SALARY * 1.2:
            # Moderately aggressive
            if tight_supply:
                bid = min(my_budget, max(DAILY_SALARY * 0.7, highest_prev_bid * 0.9))
            else:
                bid = min(my_budget, max(DAILY_SALARY * 0.5, highest_prev_bid * 0.65))
        else:
            # Mostly low bidders (David low, others possibly failed)
            bid = min(my_budget, DAILY_SALARY * (0.45 if tight_supply else 0.35))

    # Ensure non-negative and do not exceed budget
    if bid < 0.0:
        bid = 0.0
    if bid > my_budget:
        bid = my_budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25.0
    MIN_SUPPLY = 15.0
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Emergency mode: If HP is critically low, bid very high to survive
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 1.15)

    # If no opponents, bid minimal to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = 0.0
    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)

    # Base bid calculation
    base_bid = DAILY_SALARY * 0.6 # Starting point, e.g., 90 for Cindy

    # Adjust bid based on opponent's previous aggressive bidding
    if max_yesterday_bid > DAILY_SALARY * 0.7: # If opponents bid significantly high yesterday (e.g., > 105)
        bid = max_yesterday_bid + 5.0 # Try to outbid them
    else:
        bid = max(base_bid, max_yesterday_bid * 1.05) # Slightly above their max if it's not too high, or base bid

    # Adjust bid based on supply scarcity
    # supply_factor is 0 when supply is max, 1 when supply is min
    supply_factor = (MAX_SUPPLY - day_context['supply']) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_adjustment = supply_factor * (DAILY_SALARY * 0.4) # Add up to 40% of salary for scarcity
    bid += supply_adjustment

    # If HP is moderately low, ensure a stronger bid
    if my_status['hp'] <= 4:
        bid = max(bid, DAILY_SALARY * 0.85) # Ensure at least 127.5 bid

    # Final bid must not exceed budget
    final_bid = min(my_status['budget'], bid)

    # Ensure bid is at least a small positive amount if budget allows and water is needed
    if final_bid <= 0 and my_status['budget'] > 0 and my_status['hp'] < EPISODE_DAYS: 
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    return max(0.0, final_bid)
